$nodeScript = @'
const fs = require('fs')
const { PNG } = require('pngjs')
const images = [
  ['reference','D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/home-v2/fixtures/navbar-reference.png'],
  ['baseline','C:/Users/Administrator/.dsh/attachments/v1/objects/3a/3a11aed43af6bbd863f34916990b7d839fbf3570f4af9c5015071b7346142dde']
]
for (const [name,path] of images) {
  const im = PNG.sync.read(fs.readFileSync(path)), counts=[]
  for (let x=400;x<1680;x++) {
    let count=0
    for (let y=24;y<58;y++) {
      const i=(y*im.width+x)*4
      if (im.data[i]>110 && im.data[i+1]>145 && im.data[i+2]>185 && im.data[i+2]-im.data[i]>45) count++
    }
    counts.push(count)
  }
  const groups=[]; let start=-1,last=-1
  for (let i=0;i<counts.length;i++) {
    if (counts[i]>=4) { if(start<0) start=i; last=i }
    else if(start>=0 && i-last>2) { if(last-start>=2) groups.push([start+400,last+400]); start=-1; last=-1 }
  }
  if(start>=0 && last-start>=2) groups.push([start+400,last+400])
  console.log(`${name}:`)
  console.log(groups.map(([a,b])=>{let peak=a,max=-1;for(let x=a;x<=b;x++){const n=counts[x-400];if(n>max){max=n;peak=x}}return `${a}-${b}(peak ${peak},${max})`}).join(' | '))
}
'@
node -e $nodeScript
